'use strict';
// Long-content renderer checks use setData in the isolated review project only.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/theme-content-review'),qa=path.join(root,'qa/four-theme-finish-20261020/content-fit');fs.mkdirSync(qa,{recursive:true});const events=[],checks=[];
async function call(tool,args){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let out='';c.stdout.on('data',b=>out+=b);c.stderr.on('data',b=>out+=b);const timer=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},40000);c.on('close',code=>{clearTimeout(timer);let r;try{r=JSON.parse(out.slice(out.indexOf('{')));}catch{return reject(Error(out));}events.push({tool,args,result:r});fs.writeFileSync(path.join(qa,'events.json'),JSON.stringify(events,null,2)+'\n');if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||r.result?.error));resolve(r.result);});});}
const load=query=>call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme=industry&review=1&controls=0&scenario='+query]);
const patch=data=>call('automation_page_action',['--action','setData','--patch',JSON.stringify(data)]);
async function measure(selectors){const source='function(){return new Promise(resolve=>{const selectors='+JSON.stringify(selectors)+';const q=wx.createSelectorQuery();selectors.forEach(s=>q.selectAll(s).boundingClientRect());q.exec(rows=>resolve(Object.fromEntries(selectors.map((s,i)=>[s,rows[i]]))));});}';let r=await call('automation_evaluate',['--fn-source',source]);for(let i=0;i<4&&!r[selectors[0]];i++)r=r.result||r.data||r;return r;}
async function shot(name,selector){await call('simulator_screenshot',['--path',path.join(qa,name+'.png'),'--optimize','false','--wait-for-selector',selector]);}
(async()=>{
 await load('quiz');const optionText=['莲','棉花','茶树','柑橘'];await patch({'challenge.question.title':'湘潭县重点发展的“湘莲”产业与哪种植物相关？','challenge.question.options':optionText,options:optionText.map((text,index)=>({index,letter:String.fromCharCode(65+index),text,selected:false,correct:false}))});await shot('two-line-quiz','.question-title');let r=await measure(['.panel-body','.panel-scroll-frame','.quest-banner','.question-card','.option','.panel-footer']);fs.writeFileSync(path.join(qa,'quiz-geometry.json'),JSON.stringify(r,null,2)+'\n');const padding=await call('automation_element_action',['--action','style','--selector','.panel-body','--name','padding-bottom']);assert.equal(parseFloat(padding),0);const body=r['.panel-body'][0],visibleBottom=Math.min(body.bottom,r['.panel-scroll-frame'][0].bottom);assert(r['.option'].at(-1).bottom<=visibleBottom+1,'Two-line question should keep its fourth option visible');checks.push({name:'Two-line question keeps four options visible',rect:r,padding});
 if(process.argv[2]==='quiz-only'){fs.writeFileSync(path.join(qa,'quiz-followup.json'),JSON.stringify({passed:true,checks},null,2)+'\n');console.log('PASS quiz fit');return;}
 await load('home');r=await measure(['.activity-points']);assert(r['.activity-points'][0].height>=44);checks.push({name:'Home points touch target >=44px',rect:r});
 await load('home&route=points');await patch({ledger:[{id:'long-1',label:'金色产业 · 第4关 · 乡村特色产业与家乡物产观察',date:'2026/10/20',points:30},{id:'long-2',label:'金色产业 · 第3关 · 探索湖南优质特色农产品的故事',date:'2026/10/20',points:20}],'snapshot.points':50});await shot('long-ledger','.record-row');r=await measure(['.record-row','.record-copy','.record-row>.b']);r['.record-row'].forEach((row,i)=>{const text=r['.record-copy'][i],score=r['.record-row>.b'][i];assert(text.right<=score.left+1);assert(score.right<=row.right+1);});checks.push({name:'Long ledger copy stays clear of points',rect:r});
 await load('home&route=profile');await patch({'profile.nickname':'爱读书的湖湘乡村文化探索者'});await shot('long-profile','.profile-card');r=await measure(['.profile-card','.profile-card>.h2']);assert(r['.profile-card>.h2'][0].right<=r['.profile-card'][0].right);checks.push({name:'Long nickname stays in profile card',rect:r});
 await load('certificate');const d=(await call('automation_page_action',['--action','getData'])).data;await patch({certificates:[d.certificate,{...d.certificate,id:'all-content-fit',scope:'all',name:'四主题学习成果记录'}],'certificate.name':'湖湘乡村特色产业知识探索学习达人','certificate.userName':'爱读书的湖湘乡村文化探索者'});await call('automation_evaluate',['--fn-source','async function(){await getCurrentPages().slice(-1)[0].prepareCertificate();return true;}']);await shot('long-certificate','.certificate-switch');r=await measure(['.certificate-switch button','.certificate-paper','.certificate-preview']);assert(r['.certificate-switch button'].every(b=>b.height>=44));assert(r['.certificate-preview'][0].right<=r['.certificate-paper'][0].right);checks.push({name:'Certificate switch touch targets and long title fit',rect:r});
 fs.writeFileSync(path.join(qa,'checks.json'),JSON.stringify({passed:true,scope:'Native renderer with injected long display strings in isolated review data. No production records changed.',checks},null,2)+'\n');console.log('PASS content fit '+checks.length);
})().catch(e=>{fs.writeFileSync(path.join(qa,'error.txt'),e.stack+'\n');console.error(e);process.exitCode=1;});
